    `mv` also removes its sources, so they are writes too."""
    dest = args[-1]
    found = [dest]
    for src in args[:-1]:
        found.append(dest.rstrip("/") + "/" + os.path.basename(src.rstrip("/")))
        if sources_too:
            found.append(src)
    return found


